//! Protocol compatibility tests.
//!
//! Each test loads a JSON fixture generated by the Python Pydantic models
//! (`tests/generate_fixtures.py`) and verifies that the Rust types can
//! parse it. This catches field renames, missing fields, and type
//! mismatches between the two implementations.

use daemon_rs::protocol::{AnyMessage, ServerMsg};

const FIXTURES: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures");

fn load(name: &str) -> String {
    std::fs::read_to_string(format!("{FIXTURES}/{name}.json"))
        .unwrap_or_else(|e| panic!("fixture {name}.json: {e}"))
}

fn parse_command(name: &str) -> AnyMessage {
    let json = load(name);
    serde_json::from_str::<AnyMessage>(&json)
        .unwrap_or_else(|e| panic!("parse {name}.json as AnyMessage: {e}"))
}

fn parse_server_msg(name: &str) -> ServerMsg {
    let json = load(name);
    serde_json::from_str::<ServerMsg>(&json)
        .unwrap_or_else(|e| panic!("parse {name}.json as ServerMsg: {e}"))
}

// ── Client → Server commands ────────────────────────────────────

#[test]
fn set_target() {
    let msg = parse_command("set_target");
    assert!(matches!(msg, AnyMessage::SetTarget(ref c) if c.head.len() == 16));
}

#[test]
fn set_head_joints() {
    let msg = parse_command("set_head_joints");
    assert!(matches!(msg, AnyMessage::SetHeadJoints(ref c) if c.joints.len() == 7));
}

#[test]
fn set_body_yaw() {
    let msg = parse_command("set_body_yaw");
    assert!(matches!(msg, AnyMessage::SetBodyYaw(ref c) if (c.body_yaw - 0.5).abs() < 1e-9));
}

#[test]
fn set_antennas() {
    let msg = parse_command("set_antennas");
    assert!(matches!(msg, AnyMessage::SetAntennas(ref c) if c.antennas.len() == 2));
}

#[test]
fn set_full_target() {
    let msg = parse_command("set_full_target");
    assert!(matches!(msg, AnyMessage::SetFullTarget(ref c)
        if c.head.is_some() && c.antennas.is_some() && c.body_yaw.is_some()));
}

#[test]
fn set_full_target_partial() {
    let msg = parse_command("set_full_target_partial");
    assert!(matches!(msg, AnyMessage::SetFullTarget(ref c)
        if c.head.is_none() && c.antennas.is_some() && c.body_yaw.is_none()));
}

#[test]
fn goto_target() {
    let msg = parse_command("goto_target");
    assert!(matches!(msg, AnyMessage::GotoTarget(ref c)
        if c.head.is_some() && (c.duration - 2.0).abs() < 1e-9));
}

#[test]
fn goto_target_minimal() {
    let msg = parse_command("goto_target_minimal");
    assert!(matches!(msg, AnyMessage::GotoTarget(ref c)
        if c.head.is_none() && c.antennas.is_none()));
}

#[test]
fn wake_up() {
    assert!(matches!(parse_command("wake_up"), AnyMessage::WakeUp));
}

#[test]
fn goto_sleep() {
    assert!(matches!(parse_command("goto_sleep"), AnyMessage::GotoSleep));
}

#[test]
fn play_sound() {
    let msg = parse_command("play_sound");
    assert!(matches!(msg, AnyMessage::PlaySound(ref c) if c.file == "hello.wav"));
}

#[test]
fn set_motor_mode() {
    let msg = parse_command("set_motor_mode");
    assert!(matches!(msg, AnyMessage::SetMotorMode(ref c) if c.mode == "enabled"));
}

#[test]
fn set_torque() {
    let msg = parse_command("set_torque");
    assert!(matches!(msg, AnyMessage::SetTorque(ref c) if c.on && c.ids.is_none()));
}

#[test]
fn set_torque_with_ids() {
    let msg = parse_command("set_torque_with_ids");
    assert!(matches!(msg, AnyMessage::SetTorque(ref c) if !c.on && c.ids.is_some()));
}

#[test]
fn get_motor_mode() {
    assert!(matches!(parse_command("get_motor_mode"), AnyMessage::GetMotorMode));
}

#[test]
fn set_gravity_compensation() {
    let msg = parse_command("set_gravity_compensation");
    assert!(matches!(msg, AnyMessage::SetGravityCompensation(ref c) if c.enabled));
}

#[test]
fn set_automatic_body_yaw() {
    let msg = parse_command("set_automatic_body_yaw");
    assert!(matches!(msg, AnyMessage::SetAutomaticBodyYaw(ref c) if !c.enabled));
}

#[test]
fn get_state() {
    assert!(matches!(parse_command("get_state"), AnyMessage::GetState));
}

#[test]
fn start_recording() {
    assert!(matches!(parse_command("start_recording"), AnyMessage::StartRecording));
}

#[test]
fn stop_recording() {
    assert!(matches!(parse_command("stop_recording"), AnyMessage::StopRecording));
}

#[test]
fn append_record() {
    assert!(matches!(parse_command("append_record"), AnyMessage::AppendRecord(_)));
}

// ── Task protocol ───────────────────────────────────────────────

#[test]
fn task_goto() {
    let msg = parse_command("task_goto");
    assert!(matches!(msg, AnyMessage::Task(ref t) if t.uuid == "12345678-1234-5678-1234-567812345678"));
}

#[test]
fn task_play_move() {
    let msg = parse_command("task_play_move");
    assert!(matches!(msg, AnyMessage::Task(_)));
}

// ── Server → Client messages ────────────────────────────────────
//
// These test that Rust can *deserialize* the Python format.
// In practice Rust serializes (not deserializes) ServerMsg, but
// round-trip parsing catches field name mismatches.

#[test]
fn joint_positions() {
    let msg = parse_server_msg("joint_positions");
    assert!(matches!(msg, ServerMsg::JointPositions { ref head_joint_positions, .. }
        if head_joint_positions.len() == 7));
}

#[test]
fn head_pose() {
    let msg = parse_server_msg("head_pose");
    assert!(matches!(msg, ServerMsg::HeadPose { ref head_pose }
        if head_pose.len() == 4 && head_pose[0].len() == 4));
}

#[test]
fn imu_data() {
    let msg = parse_server_msg("imu_data");
    assert!(matches!(msg, ServerMsg::ImuData { temperature, .. }
        if (temperature - 25.0).abs() < 1e-9));
}

#[test]
fn daemon_status() {
    let msg = parse_server_msg("daemon_status");
    assert!(matches!(msg, ServerMsg::DaemonStatus(ref s)
        if s.robot_name == "reachy_mini"));
}

#[test]
fn task_progress() {
    let msg = parse_server_msg("task_progress");
    assert!(matches!(msg, ServerMsg::TaskProgress { ref uuid, finished, .. }
        if uuid == "12345678-1234-5678-1234-567812345678" && finished));
}
